from collections import Counter
from itertools import product

def is_kawaii(sequence):
    L = len(sequence)
    if L == 0:
        return False

    # 1. Determine the set of used numbers and the maximum M
    used_numbers = set(sequence)
    if not used_numbers:
        return False
    M = max(used_numbers)

    # Check Condition 1: If k appears, k-1 must appear
    for k in range(2, M + 1):
        if k in used_numbers and (k - 1) not in used_numbers:
            return False

    # If M > 1 and 1 is missing (should be caught by previous loop if M>0, but safe check)
    if M >= 1 and 1 not in used_numbers:
        return False

    # 2. Check Condition 2: F_{k-1} < L_k for k=2 to M
    for k in range(2, M + 1):
        k_minus_1 = k - 1

        # Find first occurrence of k-1 (F_{k-1})
        try:
            F_k_minus_1 = sequence.index(k_minus_1)
        except ValueError:
            # Should not happen if Condition 1 passed, but safety check
            continue

        # Find last occurrence of k (L_k)
        try:
            # Note: sequence.rindex() finds the last index
            L_k = len(sequence) - 1 - sequence[::-1].index(k)
        except ValueError:
            # Should not happen if M=k
            continue

        if F_k_minus_1 >= L_k:
            return False

    return True

def count_kawaii(L, M):
    """
    Counts kawaii sequences of length L using elements from {1, ..., M}
    that also use ALL elements {1, ..., M}.
    """

    print(f"--- Starting count for L={L}, M={M} ---")

    all_sequences = []
    # Iterate through all M^L sequences
    for seq_tuple in product(range(1, M + 1), repeat=L):
        sequence = list(seq_tuple)

        # Optimization: Skip sequences that don't use all required elements {1..M}
        if len(set(sequence)) != M:
            continue

        if is_kawaii(sequence):
            all_sequences.append(sequence)

    return len(all_sequences)

# Test Case: L=5, M=3
